begin;
with j as (select * from jsonb_to_recordset($law7d0015$[{"code_id":"BK_RF","article_number":"69.1","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nК бюджетным ассигнованиям на оказание государственных (муниципальных)  услуг (выполнение работ)  относятся ассигнования на: (В редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nобеспечение выполнения функций казенных учреждений,  в том числе по оказанию государственных (муниципальных)  услуг (выполнению работ)  физическим и (или)  юридическим лицам; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпредоставление субсидий бюджетным и автономным учреждениям,  включая субсидии на финансовое обеспечение выполнения ими государственного (муниципального)  задания; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nпредоставление субсидий некоммерческим организациям,  не являющимся государственными (муниципальными)  учреждениями,  в том числе в соответствии с договорами (соглашениями)  на оказание указанными организациями государственных (муниципальных)  услуг (выполнение работ)  физическим и (или)  юридическим лицам; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nосуществление бюджетных инвестиций в объекты государственной (муниципальной)  собственности; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)  (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nзакупку товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд (за исключением бюджетных ассигнований для обеспечения выполнения функций казенного учреждения и бюджетных ассигнований на осуществление бюджетных инвестиций в объекты государственной (муниципальной)  собственности казенных учреждений) ,  в том числе в целях: (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 07.05.2013 № 104-ФЗ; от 28.12.2013 № 418-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nразработки,  закупки и ремонта вооружений,  военной и специальной техники,  продукции производственно-технического назначения и имущества в рамках государственного оборонного заказа;\n\nзакупки товаров в государственный материальный резерв;\n\nпредоставление субсидий юридическим лицам,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере. (Дополнение абзацем - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 69.1. Бюджетные ассигнования на оказание государственных (муниципальных)  услуг (выполнение работ)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"310cce0aa5e67d71fe6ec9b72a4b90db1dfee973446bc6ce4b809571402d7581"},{"code_id":"BK_RF","article_number":"69.2","version_date":"1998-07-31","article_text":"1. Государственное (муниципальное)  задание должно содержать:\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпоказатели,  характеризующие качество и (или)  объем (содержание)  оказываемых государственных (муниципальных)  услуг (выполняемых работ) ; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпорядок контроля за исполнением государственного (муниципального)  задания,  в том числе условия и порядок его досрочного прекращения;\n\nтребования к отчетности об исполнении государственного (муниципального)  задания.\n\nГосударственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг физическим и юридическим лицам также должно содержать:\n\nопределение категорий физических и (или)  юридических лиц,  являющихся потребителями соответствующих услуг;\n\nпорядок оказания соответствующих услуг;\n\nпредельные цены (тарифы)  на оплату соответствующих услуг физическими или юридическими лицами в случаях,  если законодательством Российской Федерации предусмотрено их оказание на платной основе,  либо порядок установления указанных цен (тарифов)  в случаях,  установленных законодательством Российской Федерации. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\n2. Показатели государственного (муниципального)  задания используются при составлении проектов бюджетов для планирования бюджетных ассигнований на оказание государственных (муниципальных)  услуг (выполнение работ) ,  составлении бюджетной сметы казенного учреждения,  а также для определения объема субсидий на выполнение государственного (муниципального)  задания бюджетным или автономным учреждением. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n3. Государственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг (выполнение работ)  федеральными учреждениями,  учреждениями субъекта Российской Федерации,  муниципальными учреждениями формируется в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  на срок до одного года в случае утверждения бюджета на очередной финансовый год и на срок до трех лет в случае утверждения бюджета на очередной финансовый год и плановый период (с возможным уточнением при составлении проекта бюджета) . (В редакции  федеральных законов от 08.05.2010 № 83-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nГосударственное (муниципальное)  задание в части государственных (муниципальных)  услуг,  оказываемых федеральными учреждениями,  учреждениями субъекта Российской Федерации,  муниципальными учреждениями физическим лицам,  формируется в соответствии с общероссийскими базовыми (отраслевыми)  перечнями (классификаторами)  государственных и муниципальных услуг,  оказываемых физическим лицам,  формирование,  ведение и утверждение которых осуществляется в порядке,  установленном Правительством Российской Федерации. Включение в указанные перечни (классификаторы)  положений,  приводящих к возникновению расходных обязательств субъектов Российской Федерации (муниципальных образований) ,  не допускается. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nФедеральные органы государственной власти вправе формировать государственное задание на оказание государственных услуг (выполнение работ)  федеральными учреждениями также в соответствии с федеральными перечнями (классификаторами)  государственных услуг,  не включенных в общероссийские базовые (отраслевые)  перечни (классификаторы)  государственных и муниципальных услуг,  и работ,  оказание и выполнение которых предусмотрено нормативными правовыми актами Российской Федерации. Формирование,  ведение и утверждение федеральных перечней (классификаторов)  государственных услуг и работ осуществляется в порядке,  установленном Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nОрганы государственной власти субъектов Российской Федерации (органы местного самоуправления)  вправе формировать государственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг и выполнение работ учреждениями субъекта Российской Федерации (муниципальными учреждениями муниципальных образований,  находящихся на территории данного субъекта Российской Федерации)  также в соответствии с региональным перечнем (классификатором)  государственных (муниципальных)  услуг,  не включенных в общероссийские базовые (отраслевые)  перечни (классификаторы)  государственных и муниципальных услуг,  и работ,  оказание и выполнение которых предусмотрено нормативными правовыми актами субъекта Российской Федерации (муниципальными правовыми актами) ,  в том числе при осуществлении переданных им полномочий Российской Федерации и полномочий по предметам совместного ведения Российской Федерации и субъектов Российской Федерации. Формирование,  ведение и утверждение регионального перечня (классификатора)  государственных (муниципальных)  услуг и работ осуществляется в порядке,  установленном высшим исполнительным органом субъекта Российской Федерации. Включение в указанный перечень (классификатор)  положений,  приводящих к возникновению расходных обязательств муниципальных образований,  не допускается. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРегиональные перечни (классификаторы)  государственных (муниципальных)  услуг и работ размещаются на официальном сайте для размещения информации о государственных и муниципальных учреждениях и на едином портале бюджетной системы Российской Федерации в информационно-телекоммуникационной сети \"Интернет\" в порядке,  установленном Министерством финансов Российской Федерации. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nГосударственное (муниципальное)  задание формируется для бюджетных и автономных учреждений,  а также казенных учреждений,  определенных в соответствии с решением органа государственной власти (государственн\n\nановлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)\n\nплата по соглашениям об установлении сервитута,  заключенным исполнительными органами субъектов Российской Федерации,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  которые расположены в границах городских,  сельских поселений,  находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не менее 50 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nплата за публичный сервитут,  предусмотренная решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  которые расположены в границах городских,  сельских поселений и находятся в федеральной собственности,  осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации и которые не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу не менее 50 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное. (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n(Дополнение частью - Федеральный закон от 24.07.2008 № 161-ФЗ)\n\nВ бюджеты соответствующих видов муниципальных образований подлежат зачислению неналоговые доходы по нормативам отчислений,  установленным органами государственной власти субъектов Российской Федерации в соответствии со статьей 58 настоящего Кодекса. (Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nВ бюджеты городских,  сельских поселений (внутригородских районов)  подлежат зачислению неналоговые доходы по нормативам отчислений,  установленным представительным органом муниципального района (городского округа с внутригородским делением)  в соответствии со статьями 63 и 631 настоящего Кодекса. (Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 69.2. Государственное (муниципальное)  задание","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f8b4888b69df3141f51094704adb29f3bccec6f411a90dcebab1dbf083e9017"},{"code_id":"BK_RF","article_number":"7","version_date":"1998-07-31","article_text":"К бюджетным полномочиям Российской Федерации относятся:\n\nустановление общих принципов организации и функционирования бюджетной системы Российской Федерации,  основ бюджетного процесса и межбюджетных отношений;\n\nопределение основ составления и рассмотрения проектов бюджетов бюджетной системы Российской Федерации,  утверждения и исполнения бюджетов бюджетной системы Российской Федерации,  составления,  внешней проверки,  рассмотрения и утверждения отчетов об их исполнении и осуществления контроля за их исполнением;\n\nустановление порядка составления и рассмотрения проектов федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  утверждения и исполнения федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  осуществления контроля за их исполнением,  составление,  внешняя проверка,  рассмотрения и утверждения отчетов об исполнении федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  составления отчета об исполнении консолидированного бюджета Российской Федерации;\n\nсоставление и рассмотрение проектов федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  утверждение и исполнение федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  осуществление контроля за их исполнением,  составления,  внешняя проверка,  рассмотрение и утверждение отчетов об исполнении федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  составление отчета об исполнении консолидированного бюджета Российской Федерации;\n\nустановление порядка составления и представления в федеральные органы исполнительной власти сводов утвержденных бюджетов субъектов Российской Федерации и местных бюджетов,  отчетов об исполнении консолидированных бюджетов субъектов Российской Федерации и иной бюджетной отчетности;\n\nопределение порядка установления расходных обязательств публично-правовых образований;\n\nопределение порядка установления и исполнения расходных обязательств Российской Федерации,  установление и исполнение расходных обязательств Российской Федерации;\n\nопределение порядка установления и исполнения расходных обязательств субъектов Российской Федерации и муниципальных образований,  подлежащих исполнению за счет субвенций из федерального бюджета;\n\nопределение основ формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации;\n\nопределение порядка установления нормативов отчислений доходов от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов,  местных налогов и сбор\n\nнизации и осуществления бюджетного процесса;\n\nмежбюджетные трансферты - средства,  предоставляемые одним бюджетом бюджетной системы Российской Федерации другому бюджету бюджетной системы Российской Федерации;\n\nдотации - межбюджетные трансферты,  предоставляемые на безвозмездной и безвозвратной основе без установления направлений их использования; (В редакции Федерального закона от 18.07.2017 № 172-ФЗ)\n\nбюджетные полномочия - установленные настоящим Кодексом и принятыми в соответствии с ним правовыми актами,  регулирующими бюджетные правоотношения,  права и обязанности органов государственной власти (органов местного самоуправления)  и иных участников бюджетного процесса по регулированию бюджетных правоотношений,  организации и осуществлению бюджетного процесса;\n\nсмета доходов и расходов населенного пункта,  другой территории,  не являющейся муниципальным образованием,  - утвержденный органом местного самоуправления городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя план доходов и расходов распорядителя (главного распорядителя)  средств местного бюджета,  уполномоченного местной администрацией городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя осуществлять в данном населенном пункте,  на другой территории,  входящих в состав территории городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя,  отдельные функции местной администрации; (В редакции федеральных законов от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nабзац; (Утратил силу  - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nказначейский счет - счет,  открытый в Федеральном казначействе отдельному участнику системы казначейских платежей для осуществления и отражения в системе казначейских платежей операций участника системы казначейских платежей с денежными средствами; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nединый казначейский счет - банковский счет (совокупность банковских счетов) ,  за исключением счета цифрового рубля Федерального казначейства,  открытый (открытых)  Федеральному казначейству в Центральном банке Российской Федерации в валюте Российской Федерации (в кредитных организациях - в иностранной валюте)  для совершения переводов денежных средств в целях обеспечения осуществления и отражения операций на казначейских счетах,  за исключением казначейских счетов для осуществления и отражения операций с денежными средствами Фонда национального благосостояния; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)  (В редакции  Федерального закона от 31.07.2025 № 303-ФЗ)\n\nединый счет бюджета - казначейский счет (совокупность казначейских счетов для федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации) ,  открытый (открытых)  в Федеральном казначействе отдельно по каждому бюджету бюджетной системы Российской Федерации для осуществления и отражения операций с денежными средствами по поступлениям в бюджет и перечислениям из бюджета; (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)\n\nсчет цифрового рубля Федерального казначейства - счет цифрового рубля,  открытый Федеральному казначейству оператором платформы цифрового рубля для совершения операций с цифровыми рублями; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 303-ФЗ)\n\nказначейское обслуживание - проведение Федеральным казначейством в системе казначейских платежей операций участников системы казначейских платежей с денежными средствами с их отражением на соответствующих казначейских счетах; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nказначейский мониторинг - деятельность Федерального казначейства по своевременному предупреждению и предотвращению финансовых нарушений участников системы казначейских платежей; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)  (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nучастник казначейского сопровождения - юридическое лицо,  индивидуальный предприниматель,  физическое лицо - производитель товаров,  работ,  услуг,  получающие средства,  определенные в соответствии с главой 244 настоящего Кодекса,  использование которых осуществляется после подтверждения на соответствие условиям и (или)  целям,  установленным при предоставлении средств; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nказначейское сопровождение - проведение Федеральным казначейством (финансовыми органами субъектов Российской Федерации (муниципальных образований)  операций с денежными средствами участника казначейского сопровождения; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\nгосударственные (муниципальные)  услуги (работы)  - услуги (работы) ,  оказываемые (выполняемые)  органами государственной власти (органами местного самоуправления) ,  государственными (муниципальными)  учреждениями и в случаях,  установленных законодательством Российской Федерации,  иными юридическими лицами; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nгосударственное (муниципальное)  задание - документ,  устанавливающий требования к составу,  качеству и (или)  объему (содержанию) ,  условиям,  порядку и результатам оказания государственных (муниципальных)  услуг (выполнения работ) ; (В редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nбюджетные инвестиции - бюджетные средства,  направляемые на создание или увеличение за счет средств бюджета стоимости государственного (муниципального)  имущества;\n\nналоговые расходы публично-правового образования - выпадающие доходы бюджетов бюджетной системы Российской Федерации,  обусловленные налоговыми льготами,  освобождениями и иными преференциями по налогам,  сборам,  таможенным платежам,  страховым взносам на обязательное социальное страхование,  предусмотренными в качестве мер государственной (муниципальной)  поддержки в соответствии с целями государственных (муниципальных)  программ и (или)  целями социально-экономической политики публично-правового образования,  не относящимися к государственным (муниципальным)  программам; (Дополнение абзацем - Федеральный закон от 25.12.2018 № 494-ФЗ)\n\nфинансовые органы - Министерство финансов Российской Федерации,  исполнительные органы субъектов Российской Федерации,  осуществляющие составление и организацию исполнения бюджетов субъектов Российской Федерации (финансовые органы субъектов Российской Федерации) ,  органы (должностные лица)  местных администраций муниципальных образований,  осуществляющие составление и организацию исполнения местных бюджетов (финансовые органы муниципальных образований) ; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nглавный распорядитель бюджетных средств (главный распорядитель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  а также наиболее значимое учреждение науки,  образования,  культуры и здравоохранения,  указанное в ведомственной структуре расходов бюджета,  имеющие право распределять бюджетные ассигнования и лимиты бюджетных обязательств между подведомственными распорядителями и (или)  получателями бюджетных средств,  если иное не установлено настоящим Кодексом;\n\nраспорядитель бюджетных средств (распорядитель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  казенное учреждение,  имеющие право распределять бюджетные ассигнования и лимиты бюджетных обязательств между подведомственными распорядителями и (или)  получателями бюджетных средств; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nполучатель бюджетных средств (получатель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  находящееся в ведении главного распорядителя (распорядителя)  бюджетных средств казенное учреждение,  имеющие право на принятие и (или)  исполнение бюджетных обязательств от имени публично-правового образования за счет средств соответствующего бюджета,  если иное не установлено настоящим Кодексом; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nказенное учреждение - государственное (муниципальное)  учреждение,  осуществляющее оказание государственных (муниципальных)  услуг,  выполнение работ и (или)  исполнение государственных (муниципальных)  функций в целях обеспечения реализации предусмотренных законодательством Российской Федерации полномочий органов государственной власти (государственных органов)  или органов местного самоуправления,  финансовое обеспечение деятельности которого осуществляется за счет средств соответствующего бюджета на основании бюджетной сметы; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nполучатель средств из бюджета - юридическое лицо (не являющееся участником бюджетного процесса,  бюджетным и автономным учреждением) ,  индивидуальный предприниматель,  физическое лицо - производитель товаров,  работ,  услуг,  получающие средства из бюджета на основании государственного (муниципального)  контракта на поставку товаров,  выполнение работ,  оказание услуг,  договора (соглашения)  о предоставлении субсидии,  договора о предоставлении бюджетных инвестиций,  а также юридическое лицо,  которому в случаях,  установленных федеральным законом,  открываются счета в Федеральном казначействе в соответствии с настоящим Кодексом; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\nбюджетная смета - документ,  устанавливающий в соответствии с классификацией расходов бюджетов лимиты бюджетных обязательств казенного учреждения; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nведомственная структура расходов бюджета - распределение бюджетных ассигнований,  предусмотренных законом (решением)  о бюджете,  по главным распорядителям бюджетных средств,  разделам,  подразделам,  целевым статьям,  группам (группам и подгруппам)  видов расходов бюджетов либо по главным распорядителям бюджетных средств,  разделам,  подразделам и (или)  целевым статьям (государственным (муниципальным)  программам и непрограммным направлениям деятельности) ,  группам (группам и подгруппам)  видов расходов классификации расходов бюджетов; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nадминистратор доходов бюджета - орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  Центральный банк Российской Федерации,  казенное учреждение,  осуществляющие в соответствии с законодательством Российской Федерации контроль за правильностью исчисления,  полнотой и своевременностью уплаты,  начисление,  учет,  взыскание и принятие решений о возврате (зачете)  излишне уплаченных (взысканных)  платежей,  пеней и штрафов по ним,  являющихся доходами бюджетов бюджетной системы Российской Федерации,  если иное не установлено настоящим Кодексом; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nглавный администратор доходов бюджета - определенный в соответствии с настоящим Кодексом орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  Центральный банк Российской Федерации,  иная организация,  имеющие в своем ведении администраторов доходов бюджета и (или)  являющиеся администраторами доходов бюджета; (В редакции Федерального закона от 01.07.2021 № 251-ФЗ)\n\nадминистратор источников финансирования дефицита бюджета (администратор источников финансирования дефицита соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  иная организация,  имеющие право в соответствии с настоящим Кодексом осуществлять операции с источниками финансирования дефицита бюджета;\n\nглавный администратор источников финансирования дефицита бюджета (главный администратор источников финансирования дефицита соответствующего бюджета)  - определенный в соответствии с настоящим Кодексом орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  иная организация,  имеющие в своем ведении администраторов источников финансирования дефицита бюджета и (или)  являющиеся администраторами источников финансирования дефицита бюджета; (В редакции Федерального закона от 01.07.2021 № 251-ФЗ)\n\nгосударственная или муниципальная гарантия (государственная гарантия Российской Федерации,  государственная гарантия субъекта Российской Федерации,  муниципальная гарантия)  - вид долгового обязательства,  в силу которого соответственно Российская Федерация,  субъект Российской Федерации,  муниципальное образование (гарант)  обязаны при наступлении предусмотренного в гарантии события (гарантийного случая)  уплатить лицу,  в пользу которого предоставлена гарантия (бенефициару) ,  по его письменному требованию определенную в обязательстве денежную сумму за счет средств соответствующего бюджета в соответствии с условиями даваемого гарантом обязательства отвечать за исполнение третьим лицом (принципалом)  его обязательств перед бенефициаром;\n\nобоснование бюджетных ассигнований - документ,  характеризующий бюджетные ассигнования в очередном финансовом году (очередном финансовом году и плановом периоде) ;\n\nлимит бюджетных обязательств - объем прав в денежном выражении на принятие казенным учреждением бюджетных обязательств и (или)  их исполнение в текущем финансовом году (текущем финансовом году и плановом периоде) ; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nтекущий финансовый год - год,  в котором осуществляется исполнение бюджета,  составление и рассмотрение проекта бюджета на очередной финансовый год (очередной финансовый год и плановый период) ;\n\nочередной финансовый год - год,  следующий за текущим финансовым годом;\n\nплановый период - два финансовых года,  следующие за очередным финансовым годом;\n\nотчетный финансовый год - год,  предшествующий текущему финансовому году;\n\nвременный кассовый разрыв - прогнозируемая в определенный период текущего финансового года недостаточность на едином казначейском счете или на едином счете бюджета денежных средств,  необходимых для осуществления перечислений из бюджета; (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)\n\nдолговая устойчивость - состояние,  структура и сумма задолженности,  позволяющие заемщику в полном объеме выполнять обязательства по погашению и обслуживанию этой задолженности,  исключающие нанесение ущерба социально-экономическому развитию и необходимость ее списания и (или)  реструктуризации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nденежные обязательства перед публично-правовым образованием - обязанность должника уплатить публично-правовому образованию денежные средства по гражданско-правовой сделке (в том числе обеспечивающей исполнение обязательств)  и (или)  иному основанию,  установленному гражданским или бюджетным законодательством,  возникшая в связи с предоставлением публично-правовым образованием на возвратной и возмездной (возвратной)  основе денежных средств (в том числе в связи с привлечением целевых иностранных кредитов)  или в связи с предоставлением и (или)  исполнением государственной (муниципальной)  гарантии (включая обязанность по уплате процентов,  неустойки (пеней,  штрафов) ,  иных платежей,  установленных законом и (или)  договором,  вследствие неосновательного обогащения,  причинения убытков,  неисполнения или ненадлежащего исполнения обязательств,  уступки или перехода по иным основаниям прав требования,  предъявления регрессных требований) ; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nвременно свободные средства - остаток денежных средств,  образовавшийся на едином казначейском счете или на едином счете бюджета вследствие разницы в сроках и объемах поступлений (зачислений)  на счет и переводов (перечислений)  со счета. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Глава в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 7. Бюджетные полномочия Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3378c4ce967c1de612876bab4434c77c5660c2dd5054e44ee6440c95b717c6b8"},{"code_id":"BK_RF","article_number":"70","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nОбеспечение выполнения функций казенных учреждений включает: (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nоплату труда работников казенных учреждений,  денежное содержание (денежное вознаграждение,  денежное довольствие,  заработную плату)  работников органов государственной власти (государственных органов) ,  органов местного самоуправления,  лиц,  замещающих государственные должности Российской Федерации,  государственные должности субъектов Российской Федерации и муниципальные должности,  государственных и муниципальных служащих,  иных категорий работников,  командировочные и иные выплаты в соответствии с трудовыми договорами (служебными контрактами,  контрактами)  и законодательством Российской Федерации,  законодательством субъектов Российской Федерации и муниципальными правовыми актами; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nзакупки товаров,  работ,  услуг для обеспечения государственных (муниципальных)  нужд; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nуплату налогов,  сборов и иных обязательных платежей в бюджетную систему Российской Федерации;\n\nвозмещение вреда,  причиненного казенным учреждением при осуществлении его деятельности. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 70. Обеспечение выполнения функций казенных учреждений","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dacc87f33f2e9d42b445cf94078f074fd5265c61663eae2561a442211687a3a2"},{"code_id":"BK_RF","article_number":"71","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 71.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"72","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\n1. Закупки товаров,  работ,  услуг для обеспечения государственных (муниципальных)  нужд осуществляются в соответствии с законодательством Российской Федерации о контрактной системе в сфере закупок товаров,  работ,  услуг для обеспечения государственных и муниципальных нужд с учетом положений настоящего Кодекса. (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\n2. Государственные (муниципальные)  контракты заключаются в соответствии с планом-графиком закупок товаров,  работ,  услуг для обеспечения государственных (муниципальных)  нужд,  сформированным и утвержденным в установленном законодательством Российской Федерации о контрактной системе в сфере закупок товаров,  работ,  услуг для обеспечения государственных и муниципальных нужд порядке (за исключением случаев,  при которых в соответствии с законодательством Российской Федерации соответствующая закупка включению в такой план-график не подлежит) ,  и оплачиваются в пределах лимитов бюджетных обязательств,  за исключением случаев,  установленных пунктом 3 настоящей статьи. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n3. Государственные контракты,  предметом которых является поставка товаров в соответствии с государственной программой вооружения,  утверждаемой Президентом Российской Федерации,  могут заключаться в пределах средств,  установленных на соответствующие цели указанной программой,  на срок ее реализации.\n\nГосударственные (муниципальные)  контракты,  предметами которых являются выполнение работ,  оказание услуг,  длительность производственного цикла выполнения,  оказания которых превышает срок действия утвержденных лимитов бюджетных обязательств,  могут заключаться в пределах средств,  установленных на соответствующие цели решениями о подготовке и реализации бюджетных инвестиций в объекты государственной (муниципальной)  собственности,  принимаемыми в соответствии со статьей 79 настоящего Кодекса,  на срок реализации указанных решений.\n\nИные государственные контракты,  заключаемые от имени Российской Федерации,  субъекта Российской Федерации,  муниципальные контракты,  заключаемые от имени муниципального образования,  предметами которых являются выполнение работ,  оказание услуг,  длительность производственного цикла выполнения,  оказания которых превышает срок действия утвержденных лимитов бюджетных обязательств,  могут заключаться в случаях,  предусмотренных соответственно нормативными правовыми актами  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  муниципальными правовыми актами местной администрации муниципального образования,  в пределах средств и на сроки,  которые установлены указанными актами,  а также в соответствии с иными решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  принимаемыми в порядке,  определяемом соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nГосударственные контракты,  предметом которых являются поставка товаров на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  и (или)  оказание услуг,  длительность оказания которых превышает срок действия утвержденных лимитов бюджетных обязательств,  предусматривающие встречные обязательства,  не связанные с предметом их исполнения,  могут заключаться в пределах средств,  предусмотренных на соответствующие цели государственными программами Российской Федерации,  государственными программами субъекта Российской Федерации,  или в пределах средств и на сроки,  которые установлены решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  принимаемыми в порядке,  определяемом соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nГосударственные или муниципальные заказчики вправе заключать государственные или муниципальные энергосервисные договоры (контракты) ,  в которых цена определена как процент стоимости сэкономленных энергетических ресурсов,  на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств. Расходы на оплату таких договоров (контрактов)  планируются и осуществляются в составе расходов на оплату соответствующих энергетических ресурсов (услуг на их доставку) .\n\nГосударственные (муниципальные)  заказчики вправе заключать государственные (муниципальные)  контракты в период отзыва лимитов бюджетных обязательств в целях их приведения в соответствие с законом (решением)  о бюджете в размере,  не превышающем объема принимаемых бюджетных обязательств,  поставленных на учет в порядке,  установленном финансовым органом. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n(Пункт в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 72. Осуществление закупок товаров,  работ,  услуг для обеспечения государственных (муниципальных)  нужд","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5ff331ee6d9f50f99ff2fb273e52b93470b8c695da47ebe87416b7211c17bbf"},{"code_id":"BK_RF","article_number":"73","version_date":"1998-07-31","article_text":"1. Получатели бюджетных средств обязаны вести реестры закупок,  осуществленных без заключения государственных или муниципальных контрактов. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n2. Реестры закупок,  осуществленных без заключения государственных или муниципальных контрактов,  должны содержать следующие сведения: (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nкраткое наименование закупаемых товаров,  работ и услуг;\n\nнаименование и местонахождение поставщиков,  подрядчиков и исполнителей услуг;\n\nцена и дата закупки.\n\n3. (Пункт утратил силу - Федеральный закон от 02.02.2006 № 19-ФЗ)","article_title":"Статья 73. Реестры закупок","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"799fc845fe82c1fd4ed26a6220deb5f401a47806755c72325836a65dce9f6c61"},{"code_id":"BK_RF","article_number":"74","version_date":"1998-07-31","article_text":"1. В законе (решении)  о бюджете могут устанавливаться условия предоставления средств из бюджета,  в соответствии с которыми предоставление таких средств осуществляется в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nПорядок доведения указанных бюджетных ассигнований и (или)  лимитов бюджетных обязательств до главных распорядителей бюджетных средств устанавливается финансовым органом.\n\nДо утверждения указанного в абзаце первом настоящего пункта порядка доведение соответствующих бюджетных ассигнований и (или)  лимитов бюджетных обязательств до главных распорядителей (распорядителей)  или получателей бюджетных средств не допускается. (В редакции Федерального закона от 14.11.2017 № 315-ФЗ)\n\n2. Контроль за соблюдением указанных в пункте 1 настоящей статьи условий осуществляется главным распорядителем бюджетных средств.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 74. Предоставление средств из бюджетов при выполнении условий","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e92578a7889a7b87b79c0f7164c6008e9456db4ad969cb38d36910cede6392f"},{"code_id":"BK_RF","article_number":"74.1","version_date":"1998-07-31","article_text":"1. К бюджетным ассигнованиям на социальное обеспечение населения относятся бюджетные ассигнования на предоставление социальных выплат гражданам либо на приобретение товаров,  работ,  услуг в пользу граждан для обеспечения их нужд в целях реализации мер социальной поддержки населения.\n\n2. Расходные обязательства на социальное обеспечение населения могут возникать в результате принятия публичных нормативных обязательств. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nБюджетные ассигнования на исполнение указанных публичных нормативных обязательств предусматриваются отдельно по каждому виду таких обязательств в виде пенсий,  пособий,  компенсаций и других социальных выплат,  а также осуществления мер социальной поддержки населения. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 74.1. Бюджетные ассигнования на социальное обеспечение населения","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81b96f1482f9bbe78fcd60de1d6f25b7ae0e5d52867ce8d20a076cb42809c780"},{"code_id":"BK_RF","article_number":"75","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 75.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"76","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 76.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"77","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 77.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"78","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 02.07.2013 № 181-ФЗ)\n\n1. Субсидии юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг предоставляются на безвозмездной и безвозвратной основе в целях возмещения недополученных доходов и (или)  финансового обеспечения (возмещения)  затрат в связи с производством (реализацией)  товаров (за исключением табачной и алкогольной продукции,  кроме алкогольной продукции,  предназначенной для экспортных поставок,  винограда,  винодельческой продукции,  произведенной из указанного винограда: вин,  игристых вин (шампанских) ,  ликерных вин с защищенным географическим указанием,  с защищенным наименованием места происхождения (специальных вин) ,  виноматериалов,  если иное не предусмотрено нормативными правовыми актами  Правительства  Российской Федерации) ,  выполнением работ,  оказанием услуг. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n2. Субсидии юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям,  а также субсидий,  указанных в пунктах 6 - 81 настоящей статьи) ,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг предоставляются: (В редакции федеральных законов от 02.07.2013 № 181-ФЗ; от 29.12.2015 № 406-ФЗ; от 18.07.2017 № 178-ФЗ; от 27.12.2018 № 504-ФЗ)\n\n1)  из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации - в случаях,  предусмотренных федеральным законом о федеральном бюджете,  федеральными законами о бюджетах государственных внебюджетных фондов Российской Федерации,  в порядке,  установленном нормативным правовым актом  Правительства  Российской Федерации и принимаемыми в соответствии с ним решениями органов государственной власти (государственных органов)  и иных организаций,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств федерального бюджета; (В редакции  федеральных законов от 02.07.2013 № 181-ФЗ,  от 19.12.2022 № 521-ФЗ)\n\n2)  из бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов - в случаях,  предусмотренных законом субъекта Российской Федерации о бюджете субъекта Российской Федерации,  законами субъектов Российской Федерации о бюджетах территориальных государственных внебюджетных фондов,  в порядке,  установленном нормативными правовыми актами высшего исполнительного органа субъекта Российской Федерации или актами уполномоченных им органов государственной власти субъекта Российской Федерации,  за исключением случаев,  указанных в пункте 21 настоящей статьи; (В редакции  федеральных законов от 02.07.2013 № 181-ФЗ,  от 19.12.2022 № 521-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n3)  из местного бюджета - в случаях,  предусмотренных решением представительного органа муниципального образования о местном бюджете,  в порядке,  установленном муниципальными правовыми актами местной администрации или актами уполномоченных ею органов местного самоуправления,  за исключением случаев,  указанных в пункте 21 настоящей статьи. (В редакции  федеральных законов от 02.07.2013 № 181-ФЗ,  от 19.12.2022 № 521-ФЗ)\n\n21. В случаях,  установленных законом субъекта Российской Федерации (муниципальным правовым актом представительного органа муниципального образования) ,  регулирующим бюджетные правоотношения,  субсидии,  указанные в подпунктах 2 и 3 пункта 2 настоящей статьи,  предоставляются из бюджета субъекта Российской Федерации (местного бюджета)  в соответствии с порядком,  установленным нормативным правовым актом  Правительства  Российской Федерации,  указанным в подпункте 1 пункта 2 настоящей статьи,  и принимаемыми в соответствии с ним решениями органов государственной власти субъектов Российской Федерации (органов местного самоуправления) ,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств бюджета субъекта Российской Федерации (главного распорядителя средств местного бюджета) . (Дополнение пунктом - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\n3. Нормативные правовые акты,  муниципальные правовые акты,  регулирующие предоставление субсидий юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг,  указанные в подпунктах 2 и 3 пункта 2 настоящей статьи,  должны соответствовать общим требованиям,  установленным Правительством Российской Федерации,  и определять: (В редакции  федеральных законов от 02.07.2013 № 181-ФЗ,  от 03.07.2016 № 345-ФЗ,  от 19.12.2022 № 521-ФЗ)\n\n1)  категории и (или)  критерии отбора юридических лиц (за исключением государственных (муниципальных)  учреждений) ,  индивидуальных предпринимателей,  физических лиц - производителей товаров,  работ,  услуг,  имеющих право на получение субсидий;\n\n2)  цели,  условия и порядок предоставления субсидий,  а также результаты их предоставления; (В редакции Федерального закона от 29.11.2021 № 384-ФЗ)\n\n3)  порядок возврата субсидий в соответствующий бюджет в случае нарушения условий,  установленных при их предоставлении; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n4)  случаи и порядок возврата в текущем финансовом году получателем субсидий остатков субсидий,  предоставленных в целях финансового обеспечения затрат в связи с производством (реализацией)  товаров,  выполнением работ,  оказанием услуг,  не использованных в отчетном финансовом году (за исключением субсидий,  предоставленных в пределах суммы,  необходимой для оплаты денежных обязательств получателя субсидии,  источником финансового обеспечения которы\n\nударственное (муниципальное)  задание формируется для бюджетных и автономных учреждений,  а также казенных учреждений,  определенных в соответствии с решением органа государственной власти (государственного органа) ,  органа местного самоуправления,  осуществляющего бюджетные полномочия главного распорядителя бюджетных средств. (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\n31. (Дополнение пунктом - Федеральный закон от 23.07.2013 № 252-ФЗ)  (Утратил силу - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n4. Финансовое обеспечение выполнения государственных (муниципальных)  заданий осуществляется за счет средств федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местных бюджетов в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nОбъем финансового обеспечения выполнения государственного (муниципального)  задания рассчитывается на основании нормативных затрат на оказание государственных (муниципальных)  услуг,  утверждаемых в порядке,  предусмотренном абзацем первым настоящего пункта,  с соблюдением общих требований,  определенных федеральными органами исполнительной власти,  осуществляющими функции по выработке государственной политики и нормативно-правовому регулированию в установленных сферах деятельности. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 252-ФЗ)\n\nПо решению органа государственной власти,  государственного органа (органа местного самоуправления) ,  осуществляющих в соответствии с законодательством Российской Федерации функции и полномочия учредителя государственных (муниципальных)  учреждений,  при определении объема финансового обеспечения выполнения государственного (муниципального)  задания используются нормативные затраты на выполнение работ. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 252-ФЗ)\n\n5. Порядки формирования государственного (муниципального)  задания и финансового обеспечения выполнения государственного (муниципального)  задания,  устанавливаемые в соответствии с пунктами 3 и 4 настоящей статьи,  должны определять в том числе:\n\n1)  правила и сроки формирования,  изменения,  утверждения государственного (муниципального)  задания,  отчета о его выполнении;\n\n2)  правила и сроки определения объема финансового обеспечения выполнения государственного (муниципального)  задания,  включая:\n\nрасчет и утверждение нормативных затрат на оказание государственных (муниципальных)  услуг на основе базовых нормативов затрат на оказание государственных (муниципальных)  услуг и корректирующих коэффициентов к ним,  а также нормативных затрат на выполнение работ;\n\nсроки и объемы перечисления субсидии на финансовое обеспечение выполнения государственного (муниципального)  задания;\n\nвозврат субсидии в объеме,  который соответствует показателям государственного (муниципального)  задания,  которые не были достигнуты (с учетом допустимых (возможных)  отклонений) ,  в случае,  если государственное (муниципальное)  задание является невыполненным; (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\n3)  правила осуществления контроля за выполнением государственного (муниципального)  задания государственным (муниципальным)  учреждением органами государственной власти (органами местного самоуправления) ,  осуществляющими функции и полномочия учредителя.\n\n(Дополнение пунктом - Федеральный закон от 29.12.2015 № 406-ФЗ)\n\n6. Государственное (муниципальное)  задание является невыполненным в случае недостижения (превышения допустимого (возможного)  отклонения)  показателей государственного (муниципального)  задания,  характеризующих объем оказываемых государственных (муниципальных)  услуг (выполняемых работ) ,  а также показателей государственного (муниципального)  задания,  характеризующих качество оказываемых государственных (муниципальных)  услуг (выполняемых работ) ,  если такие показатели установлены в государственном (муниципальном)  задании. (Дополнение пунктом - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 78. Предоставление субсидий юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  физическим лицам","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd9a4bf097ecef397fd1e3cc9330de4a59b35084b17e1e3e98ab14bddcf279ea"}]$law7d0015$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
